with flagged as (select *, case when lag(started_at) over (partition by country order by started_at, id) is null or started_at > lag(started_at) over (partition by country order by started_at, id) + interval 90 days then 1 else 0 end as session_start_flag from sessions), sessionized as (select *, sum(session_start_flag) over (partition by country order by started_at, id rows between unbounded preceding and current row) as island_id from flagged) select customer_id, island_id, sum(case when country = 'DE' then session_start_flag else 0 end) as de_session_start_flag, round(sum(island_id) / nullif(count(case when browser = 'Safari' then 1 end), 0), 2) as island_id_per_safari, approx_percentile(island_id, 0.95) as island_id_p95 from sessionized group by customer_id, island_id order by customer_id nulls first;
